                    // The commit status below remains the authoritative signal.
                    if (candidateCommit) {
                        try {
                            publishGitHubReport(statusCredentialsId, candidateCommit, terminalStatus, candidatePr ?: '')
                        } catch (err) {
                            echo "WARNING: could not publish the GitHub CI report: ${err}"
                            terminalDescription = "${terminalDescription} (report not posted)".take(140)
                        }
                    }
                    archiveArtifacts allowEmptyArchive: true,
                        artifacts: 'ci-selection.txt,ci-baseline-preflight.txt,ci-candidate-commit.txt,ci-baseline-commit.txt,ci-report.md,*-unit-results.txt,*-c-compile-seconds.txt,ci-timing-summary.txt,ci-regression-summary.txt,ci-failure-summary.txt,slurm-*.out,slurm-*-job-id.txt,slurm-*-job-status.txt,build/**/*.log,gkylsoft/gkeyll-results/**/regressiondb,gkylsoft/gkeyll-results/**/_rr_failures.txt,_baseline/gkylsoft/gkeyll-results/**/regressiondb,_baseline/gkylsoft/gkeyll-results/**/_rr_failures.txt'
                } catch (err) {
                    terminalStatus = 'error'
                    terminalDescription = 'Stellar CPU CPU CI artifact archival failed.'
                    throw err
                } finally {
                    try {
                        if (candidateCommit) {
                            publishGitHubCommitStatus(
                                statusCredentialsId,
                                candidateCommit,
                                terminalStatus,
                                terminalDescription
                            )
                        }
                    } finally {
                        deleteDir()
                    }
                }
            }
        }
    }

